   if(b.type==='sorter'){const u=h.hub;u.sorters++;u.sortFocus??=b.id;if(WORKING_STATUS.has(b.status))u.sortWork++;else if(BLOCKED_STATUS.has(b.status)&&!u.sortBlock){u.sortBlock=b.status;u.sortFocus=b.id;}}
