const station=(id,n,sub,tone)=>{put(`st-${id}-n`,n);put(`st-${id}-sub`,sub);putClass(`st-${id}`,'station tone-'+tone);};
const parts=list=>list.filter(([n])=>n>0).map(([n,t])=>fmt(n)+' '+t).join(' · ');
function renderHud(h){
 const s=sim.state;hudData=h;
 put('siteCode',h.code);put('siteName',h.siteName);put('flowSite',h.code+' · '+h.siteName);put('siteStatus',`Rampen ${h.busy}/${h.docks} · Lager ${fmt(h.used)}/${fmt(h.cap)}`);
 put('clock',time(s.t));put('shiftName',shiftName(s.t));put('cash',euro(s.money));
 put('simState',!writable&&!temporary?'Schreibgeschützt':document.hidden?'Hintergrundpause':speed?'Betrieb läuft':'Pausiert');
 put('kpiDelivered',fmt(h.today));put('kpiDeliveredSub',h.day?`Stück · Δ ${signed(h.today-h.yesterday)} ggü. gestern (${fmt(h.yesterday)})`:'Stück · erster Spieltag');
 put('kpiVehicles',`${fmt(h.atSite)} / ${fmt(h.away)}`);put('kpiVehiclesSub',h.fleetSite?[`Fahrzeuge ${h.code}`,parts([[h.loading,'Beladung'],[h.returning,'Rückfahrt']])].filter(Boolean).join(' · '):`Keine Fahrzeuge an ${h.code}`);
 const total=h.onTime+h.late;put('kpiPunctual',total?fmt(Math.round(h.onTime/total*100))+' %':'—');put('kpiPunctualSub',total?`${fmt(h.onTime)} pünktlich · ${fmt(h.late)} verspätet`:'Noch keine Zustellung');
 const i=h.inbound,inboundOpen=i.waiting+i.receiving+i.checking+i.storing;
 renderHubStations(h);
 putHidden('stl-inbound',!(h.mfg||inboundOpen+i.ordered>0));putHidden('stl-production',!h.mfg);putHidden('stl-quality',!h.mfg);
 station('inbound',fmt(inboundOpen),parts([[i.ordered,'unterwegs'],[i.waiting,'wartet'],[i.receiving,'Annahme'],[i.checking,'Prüfung'],[i.storing,'Einlagerung']])||'Keine offenen Einkäufe',i.blocked?'wait':inboundOpen?'move':'neutral');
 const pct=h.cap?Math.round(h.used/h.cap*100):0;
 station('stock',`${fmt(h.used)}/${fmt(h.cap)}`,`${fmt(Math.max(0,h.cap-h.used))} frei · ${pct} % belegt`,h.used>=h.cap?'bad':pct>=90?'wait':'neutral');
 for(const [id,g,none] of [['production',h.prod,'Kein Montageplatz'],['quality',h.qa,'Keine Prüf- oder Packstation']])station(id,`${g.work}/${g.all}`,!g.all?none:g.block?'Engpass: '+label(g.block):g.work?'Läuft':'Bereit',g.broken?'bad':g.block?'wait':g.work?'move':'neutral');
 putHidden('stl-service',!(h.mfg||h.returnsOpen+h.ticketsOpen+h.ticketsWork>0));
 station('service',fmt(h.returnsOpen+h.ticketsOpen+h.ticketsWork),parts([[h.returnsOpen,'Rückläufe'],[h.ticketsOpen,'Tickets offen'],[h.ticketsWork,'in Bearbeitung']])||'Keine offenen Vorgänge',h.returnsDecision||h.ticketsOpen?'wait':'neutral');
 put('sbDocks',`Rampen ${h.busy}/${h.docks}`);put('sbVehicles',`Fahrzeuge ${fmt(h.fleetSite)}`);put('sbStaff',`Personal ${fmt(h.staffOn)}/${fmt(h.staffAll)} im Dienst`);put('sbStock',`Lager ${fmt(h.used)}/${fmt(h.cap)}`);
 put('vbarCount',fmt(h.vehicles.length));putHidden('vbarEmpty',h.vehicles.length>0);put('vbarSummary',h.vehicles.length?parts([[h.fleet.move,'unterwegs'],[h.fleet.wait,'wartet'],[h.fleet.bad,'Wartung nötig'],[h.fleet.neutral,'vor Ort / bereit'],[h.fleet.foreign,'Fremd-Lkw']]):'Keine Fahrzeuge');
 putHidden('kpiSortedBox',h.sorted==null);if(h.sorted!=null){put('kpiSorted',fmt(h.sorted));put('kpiSortedSub',h.sortedTotal!=null?`Pakete · gesamt ${fmt(h.sortedTotal)}`:'Pakete sortiert');}
 if(!document.body.classList.contains?.('vbar-collapsed'))syncList($('#vbarList'),h.vehicles,vehicleRow,updateVehicleRow);
 const n=h.alerts.length;put('bellCount',n>99?'99+':fmt(n));putHidden('bellCount',!n);putClass('bellCount','bell-count'+(h.alerts.some(a=>a.tone==='bad')?'':' wait'));putAttr('bellBtn','aria-label',n?`Meldungen: ${n} offen`:'Meldungen: keine');
 put('bellSummary',n?`${fmt(n)} Hinweise aus dem aktuellen Betrieb`:'Keine Meldungen. Betrieb ohne Wartegründe.');
 if(!$('#bellMenu').hidden)syncList($('#bellList'),h.alerts.slice(0,80),alertRow,updateAlertRow);
 putHidden('labelGroup',typeof scene.setLabels!=='function');
 const req=requirements(),idx=req.findIndex(x=>!x.ok),m=req[idx]||{title:'Erster Kreislauf geschlossen.',text:'Neue Aufträge, größere Kapazität, dein nächster Schritt.',panel:'overview',cta:'Betrieb weiterentwickeln'};
 put('missionNumber',idx<0?'✓':String(idx+1).padStart(2,'0'));put('missionTitle',m.title);put('missionText',m.text);
 const mk=m.cta+'|'+(m.panel||m.action)+'|'+(m.build||'');if(hudCache.get('mission')!==mk){hudCache.set('mission',mk);const a=$('#missionAction');a.textContent=m.cta+' →';delete a.dataset.panel;delete a.dataset.action;delete a.dataset.id;if(m.panel)a.dataset.panel=m.panel;else a.dataset.action=m.action;if(m.build)a.dataset.id=m.build;}
}
function vehicleRow(v){const b=el('button',v.arrival?'vrow foreign':'vrow');b.type='button';if(v.arrival)b.dataset.arrival=v.arrival;else b.dataset.vehicle=v.id;b.setAttribute('role','listitem');b._name=el('b');b._id=el('small');const c1=el('span');c1.appendChild(b._name);c1.appendChild(b._id);b._type=el('span');b._route=el('span');const c4=el('span');b._chip=el('span','chip');c4.appendChild(b._chip);b._rest=el('span','num');for(const x of [c1,b._type,b._route,c4,b._rest])b.appendChild(x);return b;}
function updateVehicleRow(b,v){setT(b._name,v.name);setT(b._id,v.id);setT(b._type,v.type);setT(b._route,v.route);setT(b._chip,v.status);setC(b._chip,'chip tone-'+v.tone);setT(b._rest,v.rest);const t=`${v.name} (${v.id}) · ${v.status}${v.hint?' · '+v.hint:''}`;if(b._title!==t){b._title=t;b.title=t;}}
function alertRow(a){const b=el('button','drop-row');b.type='button';b.dataset.alert=a.key;b.setAttribute('role','listitem');b._dot=el('span','dot');const txt=el('span');b._title=el('b');b._sub=el('small');txt.appendChild(b._title);txt.appendChild(b._sub);b._kind=el('span','kind');for(const x of [b._dot,txt,b._kind])b.appendChild(x);return b;}
function updateAlertRow(b,a){setC(b._dot,'dot tone-'+a.tone);setT(b._title,a.title);setT(b._sub,a.sub);setT(b._kind,a.ref?'Akte →':'Öffnen →');}
function flushHud(force=false){const now=performance.now();if(!hudPending||(!force&&now-hudStamp<HUD_MS))return;hudStamp=now;hudPending=false;renderHud(collectHud(sim.state));}
setInterval(()=>flushHud(),HUD_MS);
for(const id of ['siteMenu','bellMenu','cmdResults'])$('#'+id).hidden=true;
function openRef(id,target){closeMenus();const hub=id&&hubPanelFor(id);if(hub){openPanel(hub,id);return;}if(id){selected=id;openPanel('detail');scene.focus?.(id);}else if(target)openPanel(target);}
const STATIONS={gate:['yard',h=>h.dockFocus],unload:['yard',h=>h.dockFocus],sort:['inventory',h=>h.hub.sortFocus],out:['inventory',h=>h.rackFocus],delivery:['orders',()=>null],inbound:['purchasing',h=>h.rackFocus],stock:['inventory',h=>h.rackFocus],production:['production',h=>h.prod.focus],quality:['production',h=>h.qa.focus],service:['service',()=>null]};
function openStation(key){const st=STATIONS[key];if(!st)return;const h=hudData||collectHud(sim.state);openPanel(st[0]);const id=st[1](h);if(id)scene.focus?.(id);}
function menuOpen(id){return !$('#'+id).hidden;}
function closeMenus(except=''){for(const [menu,btn] of [['siteMenu','siteBtn'],['bellMenu','bellBtn'],['cmdResults','cmd']])if(menu!==except&&!$('#'+menu).hidden){$('#'+menu).hidden=true;$('#'+btn).setAttribute?.('aria-expanded','false');}}
function toggleMenu(menu,btn){const open=$('#'+menu).hidden;closeMenus(menu);$('#'+menu).hidden=!open;$('#'+btn).setAttribute?.('aria-expanded',String(open));return open;}
function renderSiteMenu(){const s=sim.state;$('#siteList').innerHTML=s.sites.map(x=>{const l=siteLoad(s,x.id);return `<button class="drop-row" data-site="${esc(x.id)}" ${x.id===s.selectedSite?'aria-current="true"':''}><span class="dot ${x.id===s.selectedSite?'tone-good':''}"></span><span><b>${esc(siteCode(s,x.id))} · ${esc(x.name)}</b><small>Rampen ${l.busy}/${l.docks} · Lager ${fmt(l.used)}/${fmt(l.cap)}</small></span><span class="kind">${x.id===s.selectedSite?'Aktiv':'Wechseln'}</span></button>`;}).join('');}
/** Globale Suche über reale Objekte des aktuellen Zustands. */
function searchAll(query){const s=sim.state,q=String(query||'').trim().toLowerCase();if(!q)return [];const site=id=>s.sites.find(x=>x.id===id)?.name||'',hits=[],has=(...p)=>p.some(x=>String(x??'').toLowerCase().includes(q));
 for(const b of s.buildings)if(has(name(BUILDINGS,b.type),b.id,label(b.status)))hits.push({id:b.id,kind:'Anlage',title:name(BUILDINGS,b.type),sub:`${b.id} · ${label(b.status)} · ${site(b.site)}`,tone:b.status==='broken'?'bad':BLOCKED_STATUS.has(b.status)?'wait':WORKING_STATUS.has(b.status)?'move':'neutral'});
 for(const v of s.vehicles)if(v.status!=='rentalReturned'&&has(v.name,v.id,VEHICLES[v.type]?.name,label(v.status)))hits.push({id:v.id,kind:'Fahrzeug',title:v.name||v.id,sub:`${v.id} · ${VEHICLES[v.type]?.name||v.type} · ${label(v.status)} · ${site(v.site)}`,tone:AWAY_STATUS.has(v.status)||['tour','transfer','service'].includes(v.status)?'move':'neutral'});
 for(const o of s.orders)if(has(o.customer,o.id,name(ITEMS,o.item)))hits.push({id:o.id,kind:'Auftrag',title:o.customer,sub:`${o.id} · ${label(o.status)} · ${o.delivered}/${o.qty} × ${name(ITEMS,o.item)}`,tone:o.late?'bad':o.status==='active'?'move':'neutral'});
 searchHub(s,q,has,site,hits);
 for(const w of s.workers)if(has(w.name,w.id,name(ROLES,w.role)))hits.push({id:w.id,kind:'Person',title:w.name,sub:`${name(ROLES,w.role)} · ${onShift(w,s.t)?w.task?'Beschäftigt':'Im Dienst':'Feierabend'} · ${site(w.site)}`,tone:'neutral'});
 const rank=h=>h.id.toLowerCase()===q?0:h.title.toLowerCase().startsWith(q)?1:2;return hits.map((h,i)=>[rank(h),i,h]).sort((a,b)=>a[0]-b[0]||a[1]-b[1]).slice(0,12).map(x=>x[2]);}
function renderCmd(){const q=$('#cmd').value;cmdHits=searchAll(q);cmdIndex=Math.min(cmdIndex,Math.max(0,cmdHits.length-1));const box=$('#cmdResults');if(!q.trim()){box.hidden=true;$('#cmd').setAttribute?.('aria-expanded','false');return;}
 box.innerHTML=cmdHits.length?cmdHits.map((h,i)=>`<button class="drop-row${i===cmdIndex?' active':''}" id="hit-${i}" role="option" aria-selected="${i===cmdIndex}" data-hit="${esc(h.id)}"><span class="dot tone-${h.tone}"></span><span><b>${esc(h.title)}</b><small>${esc(h.sub)}</small></span><span class="kind">${esc(h.kind)}</span></button>`).join(''):`<p class="drop-empty">Kein Treffer für „${esc(q.trim())}“. Gesucht wird in Anlagen, Fahrzeugen, Kennzeichen, Verträgen, Aufträgen und Beschäftigten.</p>`;
 closeMenus('cmdResults');box.hidden=false;$('#cmd').setAttribute?.('aria-expanded','true');if(cmdHits.length)$('#cmd').setAttribute?.('aria-activedescendant','hit-'+cmdIndex);else $('#cmd').removeAttribute?.('aria-activedescendant');}
function openHit(id){$('#cmd').value='';renderCmd();$('#cmd').blur?.();openRef(id);}
$('#cmd').addEventListener('input',()=>{cmdIndex=0;renderCmd();});
$('#cmd').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(cmdHits.length){cmdIndex=(cmdIndex+(e.key==='ArrowDown'?1:cmdHits.length-1))%cmdHits.length;renderCmd();}}else if(e.key==='Enter'){e.preventDefault();if(cmdHits[cmdIndex])openHit(cmdHits[cmdIndex].id);}else if(e.key==='Escape'){$('#cmd').value='';renderCmd();$('#cmd').blur?.();}});
function savePrefs(){try{if(!temporary&&!portableMode)localStorage.setItem(prefsKey,JSON.stringify({...prefs,mode:sim.state.mode}));}catch{}}
function hudToggle(kind){
 if(kind==='sites'){if(toggleMenu('siteMenu','siteBtn'))renderSiteMenu();return;}
 if(kind==='bell'){if(toggleMenu('bellMenu','bellBtn')){const h=hudData||collectHud(sim.state);syncList($('#bellList'),h.alerts.slice(0,80),alertRow,updateAlertRow);}return;}
 if(kind==='flow'||kind==='vbar'){const key=kind+'Collapsed';prefs[key]=!prefs[key];applyPrefs();savePrefs();hudPending=true;flushHud(true);return;}
 if(kind==='scene'){sceneOnly=!sceneOnly;document.body.classList.toggle('scene-only',sceneOnly);$('#sceneOnlyBtn').setAttribute?.('aria-pressed',String(sceneOnly));toast(sceneOnly?'Nur Szene. Erneut ▢ drücken, um Panels einzublenden.':'Panels eingeblendet.');}
}
const titles={overview:'Betriebszentrale',production:'Fertigung',inventory:'Lager & Materialfluss',purchasing:'Beschaffung',staff:'Dein Team',orders:'Markt & Aufträge',fleet:'Fuhrpark & Touren',finance:'Unternehmensrechnung',research:'Forschung & Produkte',rules:'Betriebsregeln',network:'Unternehmensnetz',service:'Kundendienst & Rückläufe',history:'Betriebschronik',help:'Betriebshandbuch',settings:'Spiel & Einstellungen',detail:'Objektakte',planning:'Planungsvorschau',special:'Speziallogistik',contracts:'Frachtverträge',yard:'Hof & Docks'};
let panelHtml=null;
/** Panel wird nur neu geschrieben, wenn sich sein HTML geändert hat; so bleiben Fokus, Eingaben und Scrollposition erhalten. */
function renderPanel(force=false){if(!panel)return;uiStamp=performance.now();const scroll=$('#panelBody').scrollTop;$('#panelTitle').textContent=titles[panel]||panel;$('#panelEyebrow').textContent=panel==='detail'?'ALLE DATEN. EIN ZUSAMMENHANG.':'INDUSTRIE & LOGISTIK';const renderers={overview:overview,production:production,inventory:inventory,purchasing:purchasing,staff:staff,orders:orders,fleet:fleet,finance:finance,research:research,rules:rules,network:network,service:service,history:history,help:help,settings:settings,detail:detail,planning:planning,special:special,contracts:contractsPanel,yard:yardPanel};const html=(renderers[panel]||overview)();if(force!==true&&html===panelHtml)return;panelHtml=html;$('#panelBody').innerHTML=html;$('#panelBody').scrollTop=scroll;}
function overview(){const s=sim.state,req=requirements(),blocked=s.buildings.filter(b=>['materials','staff','power','storage','broken'].includes(b.status));return `<div class="numbers">${num(fmt(s.buildings.length),'Anlagen')}${num(fmt(s.orders.filter(o=>o.status==='active').length),'Aktive Aufträge')}${num(fmt(s.reputation)+' %','Reputation')}</div><section class="section"><div class="section-title"><h3>Vom leeren Hof zur ersten Zustellung</h3>${badge(req.filter(r=>r.ok).length+' / '+req.length)}</div><ol class="checklist">${req.map((r,i)=>`<li class="${r.ok?'done':''}"><span>${r.ok?'✓':i+1}</span><div><b>${r.title}</b><small>${r.text}</small></div></li>`).join('')}</ol></section>${s.buildings.length===0?`<div class="notice">Du bestimmst den Grundriss. Alternativ richtet der Aufbauassistent die Depot-Grundausstattung über reguläre, kostenpflichtige Bau-, Einstell- und Kaufbefehle ein: Laderampe, Lagerregal, eine Lagerkraft, eine Fahrperson und ein Lieferwagen. Fertigung folgt später als Geschäftsfeld „Mehrwertdienste“.</div>${button('Startbetrieb einrichten · ca. 14.500 €','starter','','primary')}`:''}<section class="section"><div class="section-title"><h3>Engpässe</h3>${badge(blocked.length+' Hinweise',blocked.length?'warn':'good')}</div>${blocked.map(b=>`<div class="list-row"><div><strong>${esc(name(BUILDINGS,b.type))}</strong><small>${label(b.status)} · ${esc(b.id)}</small></div>${button('Prüfen →','select',b.id)}</div>`).join('')||empty('Keine Anlagen blockiert','Warteursachen erscheinen hier.')}<div class="actions">${button('Planungsvorschau','panel-planning')}${button('Chronik','panel-history')}</div></section>`;}
function production(){const s=sim.state,rows=filtered(s.buildings.filter(b=>b.site===s.selectedSite));return `<div class="notice">Jede Station verarbeitet nur passende Rezepte. Material, Arbeitskraft, Energie und freie Ausgabe müssen verfügbar sein.</div>${rows.map(b=>{const j=s.jobs.find(j=>j.id===b.job);return `<div class="card"><div class="card-top"><div><h3>${esc(name(BUILDINGS,b.type))}</h3><small>${esc(b.id)} · Position ${b.x+1}/${b.y+1}</small></div>${badge(label(b.status),['materials','staff','storage','power','broken'].includes(b.status)?'warn':'')}</div>${j?progress(b.progress)+kv('Auftrag',esc(name(RECIPES,j.recipe)))+kv('Restzeit',fmt(j.remaining,1)+' Min.'):kv('Prozess',esc(name(RECIPES,b.recipe)))}${kv('Zustand',fmt(b.condition)+' %')}<div class="actions">${button('Details','select',b.id)}${button(b.enabled?'Pausieren':'Fortsetzen','toggle',b.id)}${button('Versetzen','move',b.id)}</div></div>`;}).join('')||empty('Noch keine Anlagen','Baue deine erste Linie über den Baumodus.')}<div class="actions">${button('Anlage bauen','build','','primary')}</div>`;}
function inventory(){const s=sim.state,batches=filtered(s.batches.filter(b=>b.qty>0&&b.site===s.selectedSite)),{used,cap}=siteLoad(s,s.selectedSite);return `<div class="numbers">${num(fmt(used),'Einheiten am Standort')}${num(fmt(cap),'Lagerkapazität')}${num(fmt(s.reservations.reduce((n,r)=>n+r.qty,0)),'Reservierte Einheiten')}</div>${progress(cap?used/cap:0)}<div class="table-wrap"><table><thead><tr><th>Charge / Artikel</th><th class="num">Menge</th><th>Ort</th><th>Eigentum</th><th class="num">Qualität</th><th></th></tr></thead><tbody>${batches.map(b=>`<tr><td><b>${esc(name(ITEMS,b.item))}</b><br><small class="muted">${esc(b.id)}</small></td><td class="num">${fmt(b.qty)}${b.reserved?`<br><small>${b.reserved} gebunden</small>`:''}</td><td>${esc(label(b.location))}</td><td>${esc(label(b.owner))}</td><td class="num">${fmt(b.quality)} %</td><td>${button('Akte','select',b.id)}</td></tr>`).join('')}</tbody></table></div>${!batches.length?empty('Lager leer','Bestelle Material. Eine Lagerkraft prüft und lagert jede Lieferung ein.'):''}<div class="actions">${button('Material einkaufen','panel-purchasing','','primary')}${button('Kapazität bauen','build')}</div>`;}
function purchasing(){const s=sim.state,materials=Object.fromEntries(Object.entries(ITEMS).filter(([id,v])=>['housing','board','carton','spare','metal','sensor_component'].includes(id)||v.purchasable));return `<section class="section"><h3>Material bestellen</h3><p class="fine" style="margin:9px 0 15px">Regulär: 30 Min. · Express: 10 Min. / +30 % · Premium: 45 Min. / +18 %, höhere Qualität.</p><form data-form="buy" class="form-grid">${field('Material',`<select name="item">${opts(materials)}</select>`,true)}${field('Menge','<input name="qty" type="number" min="1" max="1000" value="12" required>')}${field('Lieferant',`<select name="supplier"><option value="standard">Regulär</option><option value="express">Express</option><option value="quality">Premium</option></select>`)}<button class="primary">Verbindlich bestellen →</button></form><div class="actions">${button('Startmaterial · 12 Leuchten','buy-kit')}</div></section><section class="section"><div class="section-title"><h3>Bestellungen</h3>${badge(s.purchases.length+' Vorgänge')}</div>${filtered(s.purchases).slice().reverse().map(p=>`<div class="card"><div class="card-top"><h3>${p.qty} × ${esc(name(ITEMS,p.item))}</h3>${badge(label(p.status),p.blocked?'warn':p.status==='stored'?'good':'')}</div>${kv('Bestellwert',euro(p.cost))}${kv('Ankunft',time(p.eta))}${p.blocked?`<p>${esc(p.blocked)}</p>`:''}<small>${esc(p.id)} · ${label(p.supplier)}</small></div>`).join('')||empty('Keine offenen Bestellungen')}</section>`;}
function staff(){const s=sim.state;return `<form data-form="hire" class="form-grid"><label class="field">Rolle<select name="role">${opts(ROLES)}</select></label><button class="primary" style="grid-column:auto;align-self:end">Person einstellen</button></form><p class="fine" style="margin:10px 0 20px">Tagschicht 08–16 Uhr. Beschäftigte können nur eine Aufgabe gleichzeitig übernehmen. Lohn je aktiver Schichtminute.</p>${filtered(s.workers).map(w=>`<div class="card"><div class="card-top"><div><h3>${esc(w.name)}</h3><small>${esc(name(ROLES,w.role))} · ${euro(w.wage)}/h</small></div>${assignmentBadge(assignmentFor(s,w))}</div><div class="grid2"><div>${kv('Qualifikation',fmt(w.skill,2)+'×')}${w.training?kv('Fortbildung',fmt(w.training.remaining)+' Min.'):''}${kv('Müdigkeit',fmt(w.fatigue)+' %')}</div><div>${kv('Tätigkeit',assignmentHtml(assignmentFor(s,w)))}${kv('Standort',esc(s.sites.find(x=>x.id===w.site)?.name))}</div></div><select aria-label="Schicht für ${esc(w.name)}" data-shift="${w.id}">${['day','night','all'].map(k=>`<option value="${k}" ${k===w.shift?'selected':''}>${label(k)}</option>`).join('')}</select><div class="actions">${button('Schulen · 90 Min. / 900 €','train',w.id)}${button('Akte','select',w.id)}${s.sites.length>1?`<select aria-label="Person versetzen" data-relocate="${w.id}"><option value="">Standort wechseln …</option>${s.sites.filter(a=>a.id!==w.site).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select>`:''}${button('Entlassen','fire',w.id,'danger')}</div></div>`).join('')||empty('Dein Team wartet auf dich','Für den Depotstart: 1 Lagerkraft und 1 Fahrdienst.')}`;}
function orders(){const s=sim.state;return `<div class="notice">Erst tatsächliche Zustellung erzeugt eine Forderung. Zahlung folgt 60 Spielminuten später. Verspätete Lieferungen erhalten 10 % Preisabschlag.</div>${filtered(s.orders).map(o=>`<div class="card"><div class="card-top"><div><h3>${esc(o.customer)}</h3><small>${esc(o.id)} · ${esc(name(ITEMS,o.item))} · ${o.kind==='logistics'?'Fremdlogistik':o.kind==='manufacturing'?'Auftragsfertigung':'Eigenprodukte'}</small></div>${badge(o.late?'Frist überschritten':label(o.status),o.late?'bad':o.status==='fulfilled'?'good':'')}</div><div class="numbers">${num(`${o.delivered} / ${o.qty}`,'Geliefert')}${num(euro(o.price),'Preis / Stück')}${num(fmt(o.quality)+' %','Mindestqualität')}</div>${kv('Lieferfrist',time(o.due))}${kv('Vertragswert',euro(o.qty*o.price))}${kv('Bezahlt',euro(o.paid))}${o.status==='offer'?`<div class="actions">${button('Auftrag annehmen','accept',o.id,'primary')}${button('Akte','select',o.id)}</div>`:o.status==='active'?`${dispatchForm(s,o)}<div class="actions">${button('Akte','select',o.id)}${button('Stornieren','cancelOrder',o.id)}</div>`:button('Auftragsakte','select',o.id)}</div>`).join('')}`;}
function rentalOffer(s){return `<section class="section"><h3>Zusätzliche Fahrzeuge mieten</h3><p class="fine" style="margin:8px 0 12px">Je angefangene 1.440 Spielminuten vorausbezahlt. Erste Rate sofort. Weitere Raten bis Rückgabe, auch bei Stillstand. Keine anteilige Erstattung. Fahrtkosten, Wartung und Personal zusätzlich. Rückgabe nur leer und frei am Mietstandort.</p><form data-form="rental" class="form-grid">${field('Fahrzeug und Mietpreis',`<select name="vehicleType">${Object.entries(RENTAL_RATES).map(([id,rate])=>`<option value="${id}">${esc(VEHICLES[id].name)} · ${euro(rate)} sofort und je Spieltag · ${capacityText({type:id,capacity:VEHICLES[id].capacity})}</option>`).join('')}</select>`,true)}<p class="fine" style="grid-column:1/-1">Mietstandort: ${esc(s.sites.find(x=>x.id===s.selectedSite)?.name)}</p><button class="primary">Kostenpflichtig mieten</button></form></section>`;}
function rentalDetails(s,v){const r=(s.rentals||[]).find(r=>r.id===v.rentalId);if(!r)return '';return `${kv('Mietrate',euro(r.rate)+' / Spieltag')}${kv('Nächste Rate',time(r.nextDue))}${kv('Bisher berechnet',euro(r.rate*r.paidDays)+' · '+fmt(r.paidDays)+' Miettage')}${kv('Rückgabeort',esc(s.sites.find(x=>x.id===r.homeSite)?.name||r.homeSite))}<div class="actions">${button('Mietfahrzeug zurückgeben','returnRental',r.id)}</div>`;}
function rentalHistory(s){const returned=(s.rentals||[]).filter(r=>r.status==='returned');return returned.length?`<section class="section"><h3>Abgeschlossene Fahrzeugmieten</h3>${returned.slice().reverse().map(r=>`<div class="card"><div class="card-top"><h3>${esc(VEHICLES[r.vehicleType]?.name||r.vehicleType)}</h3>${badge('Zurückgegeben')}</div>${kv('Rückgabe',time(r.returnedAt))}${kv('Gesamte Mietkosten',euro(r.rate*r.paidDays))}<small>${esc(r.id)} · ${fmt(r.paidDays)} Miettage</small></div>`).join('')}</section>`:'';}
function fleet(){const s=sim.state;return `${rentalOffer(s)}<form class="form-grid" data-form="vehicle">${field('Fahrzeug',`<select name="vehicleType">${Object.entries(VEHICLES).map(([id,v])=>`<option value="${id}">${esc(v.name)} · ${euro(v.cost)}</option>`).join('')}</select>`,true)}<button class="primary">Fahrzeug anschaffen</button></form><section class="section" style="margin-top:22px"><h3>Deine Flotte</h3>${filtered(s.vehicles.filter(v=>v.status!=='rentalReturned')).map(v=>`<div class="card" style="margin-top:12px"><div class="card-top"><h3>${esc(v.name)}</h3>${badge(label(v.status))}</div>${kv('Kapazität',capacityText(v))}${kv('Zustand',conditionHtml(v))}${rentalDetails(s,v)}<div class="actions">${button('Akte','select',v.id)}${button('Werkstatt-Wartung','vehicleMaintain',v.id)}${button('Externe Wartung','vehicleServiceExternal',v.id)}</div></div>`).join('')||empty('Noch keine Fahrzeuge',`Lieferwagen: ${capacityText({type:'van',capacity:VEHICLES.van.capacity})}, ${euro(VEHICLES.van.cost)}.`)}</section><section class="section"><h3>Sendungen</h3>${filtered(s.shipments).slice().reverse().map(sh=>`<div class="card" style="margin-top:12px"><div class="card-top"><h3>${esc(sh.id)}</h3>${badge(label(sh.status),sh.blocked?'warn':'')}</div>${kv('Menge',fmt(sh.qty)+' Stück')}${kv('Nächster Schritt',fmt(sh.remaining)+' Min.')}${sh.blocked?`<p>${esc(sh.blocked)}</p>`:''}<div class="actions">${button('Verlauf','select',sh.id)}${sh.status==='loading'?button('Stornieren','cancelShipment',sh.id):''}</div></div>`).join('')||empty('Keine Sendungen','Plane eine Lieferung im Auftragsfenster.')}</section>${tourPanel(s)}${rentalHistory(s)}`;}
function finance(){const s=sim.state,r=report(s),deliveries=deliveryRows(s),outstanding=deliveries.filter(sh=>sh.paymentAt&&!sh.paid).reduce((n,sh)=>n+(sh.invoiceAmount||0),0),goods=s.batches.filter(b=>b.owner==='company').reduce((n,b)=>n+b.qty*b.unitCost,0),payments=s.ledger.filter(l=>l.category==='Umsatz').reduce((n,l)=>n+l.amount,0);const categories={};for(const l of s.ledger)categories[l.category]=(categories[l.category]||0)+l.amount;
 // W2b: Vertragsstrafe als eigene Kategorie, mit Frachtverträgen auch bei 0 € sichtbar.
 const penalty=s.ledger.filter(isPenaltyRow),penaltySum=Math.round(penalty.reduce((n,l)=>n+l.amount,0)*100)/100;if((s.contracts||[]).some(c=>c.status!=='offer')&&!('Vertragsstrafe' in categories))categories['Vertragsstrafe']=0;return `<div class="numbers">${num(euro(s.money),'Kontostand')}${num(euro(r.receivables.total),'Offene Forderungen')}${num(euro(r.inventory.ownValue),'Warenmodellwert')}</div><div class="notice">Zahlungsübersicht: Investitionen und Einkauf sind Geldabflüsse. Daraus allein folgt kein operativer Gewinn. Material trägt Beschaffungskosten; fertige Produkte zusätzlich direkte Fertigungslöhne und Maschinenenergie.</div><section class="section"><h3>Geldfluss seit Unternehmensgründung</h3><div class="grid2">${[['Betrieb',r.cashflow.operating],['Investitionen',r.cashflow.investing],['Finanzierung',r.cashflow.financing],['Sonstige Buchungen',r.cashflow.other]].map(([k,v])=>`<div class="card">${kv(k,euro(v))}</div>`).join('')}</div>${kv('Geldbestand zu Beginn (aus Journal)',euro(r.cash.openingBalance))}${kv('Netto-Geldfluss',euro(r.cash.net))}</section><section class="section"><h3>Gebundenes Kapital und Verpflichtungen</h3>${kv('Eigene Waren · Modellwert',euro(r.inventory.ownValue))}${kv('Davon gesperrt',euro(r.inventory.blockedValue))}${kv('Laufende Fertigung · Materialanteil',euro(r.inventory.workInProgress))}${kv('Vorausbezahlte Beschaffung',euro(r.inventory.prepaidPurchases))}${kv('Fremde Waren · kein eigenes Vermögen',fmt(r.inventory.foreignQty)+' Stück')}${kv('Offene Forderungen',euro(r.receivables.total))}${kv('Davon überfällig',euro(r.receivables.overdue))}${kv('Kredit, Überziehung und Terminalgebühren',euro(r.liabilities.total))}<details><summary>Bewertungsregeln und Grenzen</summary>${r.limitations.map(x=>`<p>${esc(x)}</p>`).join('')}</details></section><section class="section"><h3>Offene Kundenrechnungen</h3>${r.receivables.rows.map(row=>`<div class="list-row"><div><strong>${esc(row.customer)}</strong><small>${esc(row.source)} · ${esc(row.id)} · fällig ${time(row.due)}</small></div><b>${euro(row.amount)}${row.overdue?' · überfällig':''}</b></div>`).join('')||empty('Keine offenen Forderungen')}</section><div class="grid2"><div class="card"><h3>Zahlungsströme nach Bereich</h3>${Object.entries(categories).map(([k,v])=>kv(label(k),`<span class="${v<0?'money-minus':'money-plus'}">${euro(v)}</span>`)).join('')}</div><div class="card"><h3>Vertrieb</h3>${kv('Bezahlter Kundenumsatz',euro(payments))}${kv('Ausgelieferte Einheiten',fmt(s.stats.delivered))}${kv('Vertragsstrafen',`<span class="${penaltySum<0?'money-minus':''}">${euro(penaltySum)}</span> · ${fmt(penalty.length)} ${penalty.length===1?'Buchung':'Buchungen'}`)}${kv('Reputation',fmt(s.reputation)+' %')}${kv('Aktive Verträge',fmt(s.orders.filter(o=>o.status==='active').length))}</div></div><section class="section"><h3>Lieferungsbeiträge</h3><p class="fine">Rechnungswert minus bewertete Herstellung und direkte Fracht. Standortmiete, Verwaltung und Finanzierung sind noch nicht verteilt.</p><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Kunde / Route</th><th class="num">Rechnung</th><th class="num">Direkte Kosten</th><th class="num">Beitrag</th></tr></thead><tbody>${deliveries.filter(sh=>sh.deliveredAt).map(sh=>`<tr><td>${esc(s.orders.find(o=>o.id===sh.orderId)?.customer)}<br><small>${esc(sh.id)}</small></td><td class="num">${euro(sh.invoiceAmount||0)}</td><td class="num">${euro((sh.materialCost||0)+(sh.transportCost||0))}</td><td class="num">${euro((sh.invoiceAmount||0)-(sh.materialCost||0)-(sh.transportCost||0))}</td></tr>`).join('')}</tbody></table></div></section><section class="section"><h3>Finanzierung</h3>${kv('Darlehenssaldo · 8 % p.a.',euro(s.loanBalance||0))}${kv('Kontokorrent · 15 % p.a.',euro(s.overdraft||0))}<form data-form="loan" class="form-grid">${field('Betrag','<input name="amount" type="number" min="100" max="50000" value="10000" required>')}${field('Aktion','<select name="operation"><option value="takeLoan">Kredit aufnehmen</option><option value="repayLoan">Kredit tilgen</option></select>')}<button class="primary">Finanzierung ausführen</button></form><p class="fine">Pflichtkosten laufen bei Geldmangel ins Kontokorrent. Neue freiwillige Ausgaben benötigen ausreichende Liquidität.</p></section><section class="section"><div class="section-title"><h3>Buchungsjournal</h3>${badge(s.ledger.length+' Buchungen')}</div><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Bereich / Anlass</th><th class="num">Betrag</th></tr></thead><tbody>${filtered(s.ledger).slice(-120).reverse().map(l=>`<tr><td>${time(l.t)}</td><td>${esc(label(l.category))}<br><small class="muted">${esc(l.note)}</small></td><td class="num ${l.amount<0?'money-minus':'money-plus'}">${euro(l.amount)}</td></tr>`).join('')}</tbody></table></div><p class="fine">Letzte 120 Treffer. Gesamter Zustand bleibt im Export enthalten.</p></section>`;}
function research(){const s=sim.state;return `<div class="notice">Entwicklung verbindet Forschung, Personal und Anlagen. Laufende Projekte benötigen eine Entwicklungskraft und ein Labor.</div>${Object.entries(RESEARCH).map(([id,r])=>{const project=s.research.find(p=>p.key===id||p.type===id||p.id===id);return `<div class="card"><div class="card-top"><h3>${esc(r.name)}</h3>${badge(project?label(project.status):'Verfügbar')}</div>${kv('Investition',euro(r.cost))}${kv('Dauer',r.duration+' Min.')}${project?.blocked?`<p>${esc(project.blocked)}</p>`:''}${project?progress(1-(project.remaining||0)/r.duration):button('Forschung starten','research',id,'primary')}</div>`;}).join('')}<section class="section"><h3>Arbeitspläne</h3>${Object.entries(RECIPES).map(([id,r])=>`<div class="card" style="margin-top:10px"><h3>${esc(r.name)}</h3><p>${Object.entries(r.inputs).map(([i,q])=>q+' × '+esc(name(ITEMS,i))).join(' + ')} → ${r.output.qty} × ${esc(name(ITEMS,r.output.item))}</p>${kv('Nennzeit',r.duration+' Min.')}${kv('Anlage',esc(name(BUILDINGS,r.building)))}</div>`).join('')}</section>`;}
function rules(){const s=sim.state;return `<div class="notice">Betriebsregeln nutzen dieselben Material-, Personal- und Budgetgrenzen wie manuelle Eingaben. Kein zusätzlicher Ertrag durch Automatisierung.</div><form class="form-grid" data-form="rule">${field('Regelart','<select name="kind"><option value="reorder">Material nachbestellen</option><option value="dispatch">Kundenlieferungen disponieren</option><option value="maintenance">Anlagen warten</option></select>',true)}${field('Material (Nachbestellung)',`<select name="item">${opts(Object.fromEntries(Object.entries(ITEMS).filter(([id,v])=>v.purchasable)))}</select>`,true)}${field('Bestand- / Zustandsgrenze','<input name="threshold" type="number" min="1" value="5">')}${field('Menge je Bestellung / Fahrt','<input name="qty" type="number" min="1" value="20">')}${field('Gesamtbudget der Regel','<input name="budget" type="number" min="1" value="1000">')}${field('Wartezeit in Minuten','<input name="cooldown" type="number" min="10" value="120">')}${field('Priorität · höher zuerst','<input name="priority" type="number" min="0" max="100" value="50">')}<button class="primary">Betriebsregel anlegen</button></form><section class="section" style="margin-top:20px">${s.rules.map(r=>`<div class="card"><h3>${esc(r.name||(r.kind==='dispatch'?'Versandleitung':r.kind==='maintenance'?'Wartungsleitung':name(ITEMS,r.item)))}</h3>${kv('Zustand',r.enabled?'Aktiv':'Pausiert')}${kv('Budgetverbrauch',euro(r.spent||0)+' / '+euro(r.budget))}${kv('Letzte Ausführung',r.lastRun?time(r.lastRun):'Noch nicht')}${r.lastReason?`<p>${esc(r.lastReason)}</p>`:''}<div class="actions">${button(r.enabled?'Pausieren':'Aktivieren','toggleRule',r.id)}${button('Entfernen','deleteRule',r.id)}</div></div>`).join('')||empty('Keine Regeln','Starte mit einem Sicherheitsbestand für Kartons.')}</section>`;}
function network(){const s=sim.state;return `<div class="section-title"><h3>Standorte</h3>${button('Netzkarte','networkView')}</div><div class="grid2">${s.sites.map(a=>`<div class="card"><div class="card-top"><h3>${esc(a.name)}</h3>${badge(a.id===s.selectedSite?'Ausgewählt':'Standort')}</div>${kv('Fläche',a.width+' × '+a.height)}${kv('Anlagen',s.buildings.filter(b=>b.site===a.id).length)}${kv('Team',s.workers.filter(w=>w.site===a.id).length)}<div class="actions">${button('Standort öffnen','site',a.id,'primary')}</div></div>`).join('')}</div><form data-form="site" class="form-grid">${field('Neuer Standortname','<input name="name" value="Verteilzentrum Lindenhain" maxlength="60" required>',true)}<button class="primary">Standort erwerben · 25.000 €</button><small class="fine" style="grid-column:1/-1">Benötigt Forschung „Standortnetz“. Freies Bauen ohne Forschungssperre. Maximal acht Standorte.</small></form>${s.sites.length>1?`<section class="section" style="margin-top:20px"><h3>Ware zwischen Standorten transportieren</h3><form data-form="transfer" class="form-grid">${field('Artikel',`<select name="item">${opts(ITEMS)}</select>`)}${field('Menge','<input name="qty" type="number" min="1" value="10">')}${field('Ziel',`<select name="toSite">${s.sites.filter(a=>a.id!==s.selectedSite).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select>`)}${field('Fahrzeug',`<select name="vehicleId">${s.vehicles.filter(v=>v.site===s.selectedSite&&v.status==='idle').map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select>`)}<button class="primary">Transfer beauftragen</button></form></section>`:''}<section class="section" style="margin-top:20px"><h3>Standorttransfers</h3>${(s.transfers||[]).slice().reverse().map(t=>`<div class="card" style="margin-top:10px"><div class="card-top"><h3>${t.qty} × ${esc(name(ITEMS,t.item))}</h3>${badge(label(t.status),t.blocked?'warn':'')}</div>${kv('Von',esc(s.sites.find(a=>a.id===(t.fromSite||t.site))?.name))}${kv('Nach',esc(s.sites.find(a=>a.id===t.toSite)?.name))}${kv('Restzeit',fmt(t.remaining)+' Min.')}${t.blocked?`<p>${esc(t.blocked)}</p>`:''}</div>`).join('')||empty('Keine Transfers','Eigene Standorttransfers erzeugen keinen Umsatz.')}</section><div class="actions">${button('Planungsvorschau','panel-planning')}</div>`;}
const ticketKinds={status:'Statusanfrage',deadline:'Fristverlängerung',complaint:'Beschwerde'};
const ticketResponses={inform:'Status mitteilen',approve:'Frist genehmigen',reject:'Frist ablehnen',goodwill:'Kulanz gewähren',apologize:'Entschuldigen'};
const ticketOutcomes={inform:'Status mitgeteilt',approve:'Frist verlängert',reject:'Fristverlängerung abgelehnt',goodwill:'Kulanz ausgezahlt',apologize:'Entschuldigung übermittelt',obsolete:'Anliegen nicht mehr anwendbar'};
function ticketEstimate(s,t,response){const o=s.orders.find(o=>o.id===t.orderId);if(!o)return 0;if(response==='approve')return Math.round(Math.max(0,o.qty-o.delivered)*o.price*0.02*100)/100;if(response==='goodwill'&&o.paid>0)return Math.round(Math.min(50,o.paid*0.05)*100)/100;return 0;}
function ticketRespond(id,response){const t=(sim.state.tickets||[]).find(t=>t.id===id);if(!t)return;const cost=ticketEstimate(sim.state,t,response);const act=()=>send({type:'respondTicket',id,response});if(response==='approve'||response==='goodwill')return confirm(ticketResponses[response]+'?',`Voraussichtliche Kosten: ${euro(cost)}. Betrag wird vom Simulationskern bei Ausführung geprüft. Servicepersonal bearbeitet Entscheidung; Wirkung erst nach Abschluss.`,act);return act();}
function ticketCard(s,t){const o=s.orders.find(o=>o.id===t.orderId),status={open:'Offen',processing:'In Bearbeitung',closed:'Geschlossen'}[t.status]||t.status;const responses=t.kind==='status'?['inform']:t.kind==='deadline'?['approve','reject']:['goodwill','apologize'];return `<div class="card"><div class="card-top"><div><h3>${esc(o?.customer||t.orderId)}</h3><small>${esc(t.id)} · Auftrag ${esc(t.orderId)}</small></div>${badge(esc(status),t.blocked?'warn':'')}</div>${kv('Anliegen',esc(ticketKinds[t.kind]||t.kind))}${kv('Standort',esc(s.sites.find(site=>site.id===t.site)?.name||t.site))}${kv('Eingang',time(t.createdAt))}${kv('Ursprüngliche Frist',time(t.originalDue))}${t.requestedDue!=null?kv('Beantragte Frist',time(t.requestedDue)):''}${o?kv('Aktuelle Auftragsfrist',time(o.due)):''}${kv(t.status==='closed'?'Gebuchte Kosten':'Vorgemerkte Kosten',euro(t.status==='closed'&&t.outcome==='obsolete'?0:t.cost||0))}${t.status==='open'?kv('Geplante Arbeitszeit',fmt({status:15,deadline:30,complaint:20}[t.kind])+' Spielminuten'):t.status==='processing'?kv('Verbleibende Arbeitszeit',fmt(t.remaining)+' Spielminuten'):kv('Abgeschlossen',time(t.completedAt))}${t.response?kv('Gewählte Antwort',esc(ticketResponses[t.response]||t.response)):''}${t.outcome?`<p>${esc(ticketOutcomes[t.outcome]||t.outcome)}</p>`:''}${t.status==='closed'&&t.reply?`<p class="notice">${esc(t.reply)}</p>`:''}${t.blocked?`<div class="notice" role="status">${esc(t.blocked)}</div>`:''}${t.status==='open'?`<div class="actions">${responses.filter(r=>r!=='goodwill'||o?.paid>0).map(r=>button(ticketResponses[r]+(['approve','goodwill'].includes(r)?' · ca. '+euro(ticketEstimate(s,t,r)):''),'ticket-'+r,t.id)).join('')}</div>${t.kind==='complaint'&&!(o?.paid>0)?'<p class="fine">Kulanz erst nach Kundenzahlung verfügbar.</p>':''}`:''}</div>`;}
function ticketPanel(s){const tickets=s.tickets||[],orders=s.orders.filter(o=>['active','fulfilled'].includes(o.status));return `<section class="section"><h3>Kundendienst</h3><div class="numbers">${num(tickets.filter(t=>t.status==='open').length,'Offen')}${num(tickets.filter(t=>t.status==='processing').length,'In Bearbeitung')}${num(tickets.filter(t=>t.status==='closed').length,'Geschlossen')}</div><p class="fine">Servicepersonal am Ticketstandort benötigt Arbeitszeit: Status 15, Frist 30, Beschwerde 20 Spielminuten. Schicht und Pause gelten. Überfällige Aufträge erzeugen automatisch eine Beschwerde.</p><form data-form="ticket" class="form-grid">${field('Auftrag / Kunde',`<select name="orderId" required>${orders.map(o=>`<option value="${esc(o.id)}">${esc(o.customer)} · ${esc(o.id)} · ${esc(label(o.status))}</option>`).join('')||'<option value="">Kein aktiver oder erfüllter Auftrag</option>'}</select>`,true)}${field('Anliegen','<select name="kind"><option value="status">Statusanfrage · 15 Min.</option><option value="deadline">Fristverlängerung · 30 Min.</option><option value="complaint">Beschwerde · 20 Min.</option></select>')}${field('Fristverlängerung in Spielminuten','<input name="extensionMinutes" type="number" min="60" max="1440" step="1" value="240" required>')}<p class="fine" style="grid-column:1/-1">Verlängerung nur für aktive, unvollständige Aufträge; 60–1.440 Minuten ab bisheriger Frist. Je Auftrag und Anliegen höchstens ein Ticket. Genehmigung kostet 2 % des offenen Auftragswerts. Kulanz kostet 5 % des bezahlten Betrags, höchstens 50 €; nur nach Zahlung. Status, Ablehnung und Entschuldigung ohne Zusatzgebühr; Personallöhne laufen weiter.</p><button class="primary" ${orders.length?'':'disabled'}>Ticket anlegen</button></form>${['open','processing','closed'].map(status=>`<details ${status!=='closed'?'open':''}><summary>${({open:'Offene Tickets',processing:'Tickets in Bearbeitung',closed:'Abgeschlossene Tickets'})[status]} · ${tickets.filter(t=>t.status===status).length}</summary>${tickets.filter(t=>t.status===status).slice().reverse().map(t=>ticketCard(s,t)).join('')||'<p class="fine">Keine Tickets.</p>'}</details>`).join('')}</section>`;}

function service(){const s=sim.state;return `${ticketPanel(s)}<h3 style="margin:20px 0">Retouren</h3><div class="notice">Rückläufe brauchen echte Ware, Abholung und Prüfung. Erstattung erfolgt einmalig. Gesperrte Ware bleibt unverkäuflich.</div><form data-form="return" class="form-grid">${field('Gelieferter Auftrag',`<select name="orderId">${s.orders.filter(o=>o.delivered>0).map(o=>`<option value="${o.id}">${esc(o.customer)} · ${o.delivered} geliefert</option>`).join('')||'<option value="">Noch keine Zustellung</option>'}</select>`,true)}${field('Rückgabemenge','<input name="qty" type="number" min="1" value="1">')}<button class="primary" style="grid-column:auto;align-self:end">Rücknahme beauftragen</button></form><section class="section" style="margin-top:20px">${s.returns.map(r=>`<div class="card"><div class="card-top"><h3>${esc(r.id)}</h3>${badge(label(r.status))}</div>${kv('Menge',fmt(r.qty))}${r.blocked?`<p>${esc(r.blocked)}</p>`:''}<div class="actions">${button('Reparieren','repairReturn',r.id)}${button('Verwerten','recycleReturn',r.id)}</div></div>`).join('')||empty('Keine Rückläufe','Zustellungen bilden die Grundlage späterer Rücknahmen.')}</section>`;}
function history(ref=null){const rows=filtered(sim.state.events.filter(e=>!ref||e.refs?.includes(ref))).slice(-150).reverse();return `<div class="timeline">${rows.map(e=>`<div class="timeline-item"><small>${time(e.t)} · ${esc(e.kind)}</small><p>${esc(e.text)}</p>${e.refs?.length?`<div class="actions">${e.refs.slice(0,3).map(id=>button(esc(id),'select',id)).join('')}</div>`:''}</div>`).join('')||empty('Noch keine Ereignisse')}</div>`;}
function detail(){const s=sim.state;let kind='',o;for(const k of ['buildings','workers','batches','orders','purchases','vehicles','shipments','returns','transfers','tours','freights']){o=(s[k]||[]).find(x=>x.id===selected);if(o){kind=k;break;}}if(!o)return empty('Objekt nicht gefunden','Einige abgeschlossene Arbeitsaufträge gehen in die Chronik über.');let html=`<div class="card"><div class="card-top"><h3>${esc(o.name||o.customer||name(kind==='buildings'?BUILDINGS:ITEMS,o.type||o.item)||o.id)}</h3>${badge(o.id)}</div>`;if(kind==='buildings'){const d=BUILDINGS[o.type];html+=kv('Status',label(o.status))+kv('Zustand',fmt(o.condition)+' %')+kv('Energiebedarf',d.power+' kW')+kv('Anschaffung',euro(d.cost));if(o.type==='forklift')html+=forkliftHtml(s,o);if(d.recipes.length)html+=`<label class="field">Arbeitsplan<select data-recipe="${o.id}">${d.recipes.map(id=>`<option value="${id}" ${id===o.recipe?'selected':''}>${esc(name(RECIPES,id))}</option>`).join('')}</select></label>`;html+=`<div class="actions">${button(o.enabled?'Pausieren':'Fortsetzen','toggle',o.id)}${button('Warten','maintain',o.id)}${button('Versetzen','move',o.id)}${button('Abreißen · 35 % Erlös','demolish',o.id,'danger')}</div>`;}else if(kind==='vehicles'){html+=vehicleDetail(s,o);}else if(kind==='batches'){html+=kv('Artikel',esc(name(ITEMS,o.item)))+kv('Menge',fmt(o.qty))+kv('Reserviert',fmt(o.reserved))+kv('Ort',label(o.location))+kv('Eigentum',esc(label(o.owner)))+kv('Qualität',fmt(o.quality)+' %')+kv('Einstandspreis',euro(o.unitCost));html+=`<div class="actions">${button('Charge und Nachfolger sperren','recallBatch',o.id,'danger')}</div><p>Herkunft: ${(o.parents||[]).map(id=>button(esc(id),'select',id)).join(' ')||'Direkte Anlieferung'}</p>`;}else{for(const [k,title]of Object.entries({status:'Status',role:'Rolle',item:'Artikel',qty:'Menge',delivered:'Geliefert',remaining:'Restzeit',quality:'Qualität',condition:'Zustand',blocked:'Warteursache',task:'Tätigkeit',capacity:'Ladeplätze',paid:'Bezahlt'}))if(k==='task'&&kind==='workers')html+=kv(title,assignmentHtml(assignmentFor(s,o)));else if(o[k]!==undefined)html+=kv(title,esc(k==='item'?name(ITEMS,o[k]):k==='role'?name(ROLES,o[k]):label(o[k])));}return html+'</div><h3 style="margin:20px 0">Verlauf</h3>'+history(o.id);}
function conditionHtml(v){return `${fmt(v.condition)} %${v.condition<15?' · keine Fahrt':v.condition<WEAR_WARN?' · Wartung planen':''}`;}
/** Fahrzeugakte: Kapazität je Artikelart, Zustand, beide Wartungswege mit Kosten und Dauer. */
function vehicleDetail(s,v){const m=v.maintenance,need=v.condition<100,shop=s.buildings.some(b=>b.site===v.site&&b.type==='workshop'&&b.enabled&&b.condition>0);
 let h=kv('Status',label(v.status))+kv('Typ',esc(VEHICLES[v.type]?.name||v.type))+kv('Ladevolumen',fmt(v.capacity)+' Volumeneinheiten')+kv('Nutzlast',fmt(weightCap(v))+' kg')+kv('Pakete',`≈ ${fmt(maxLoad(v,'parcel'))} (Gewichtsgrenze)`)+kv('Fertigware',`${fmt(maxLoad(v,'lamp'))} Arbeitsleuchten`)+kv('Zustand',conditionHtml(v));
 if(v.status==='maintenance'&&m)h+=kv(m.external?'Externe Wartung':'Werkstatt-Wartung',fmt(m.remaining)+' Min. verbleibend'+(m.blocked?' · '+esc(m.blocked):''));
 h+=`<p class="fine">Jede Fahrt kostet Zustand. Unter 15 % fährt das Fahrzeug nicht. Werkstatt-Wartung: Wartungswerkstatt am Standort, 1 Ersatzteil, Technikpersonal, 20 Min., ${need?euro(maintenanceCost(v)):'—'}${shop?'':' · keine Werkstatt am Standort'}. Externe Wartung: mobiler Servicepartner am Standort, ${fmt(EXTERNAL_SERVICE.minutes)} Min. außer Betrieb, ${need?euro(maintenanceCost(v,true)):'—'} (×1,5).</p>`;
 const free=v.status==='idle'&&need;return h+`<div class="actions">${free?button('Werkstatt-Wartung · '+euro(maintenanceCost(v)),'vehicleMaintain',v.id):''}${free?button(`Externe Wartung · ${euro(maintenanceCost(v,true))} · ${fmt(EXTERNAL_SERVICE.minutes)} Min.`,'vehicleServiceExternal',v.id,'primary'):''}</div>`;}
function planning(){const s=sim.state;return `<div class="notice good">Planung läuft auf vollständiger Kopie. Originalbestand, Geld und Zufallszustand bleiben unverändert. Prognose setzt heutige Befehle fort; neue Marktentscheidungen werden nicht erfunden.</div><form data-form="forecast" class="form-grid">${field('Zeitraum','<select name="minutes"><option value="60">1 Spielstunde</option><option value="480">8 Spielstunden</option><option value="1440">1 Spieltag</option></select>')}${field('Alternative','<select name="alternative"><option value="none">Aktuellen Betrieb fortführen</option><option value="worker">Zusätzliche Fertigungskraft</option></select>')}<button class="primary">Vorschau berechnen</button></form>${forecast?`<div class="forecast-comparison" style="margin-top:20px"><div class="card"><h3>Jetzt</h3>${kv('Geld',euro(s.money))}${kv('Fertigware erzeugt',s.stats.produced)}${kv('Ausgeliefert',s.stats.delivered)}</div><div class="card"><h3>${time(forecast.t)}</h3>${kv('Geld',euro(forecast.money))}${kv('Fertigware erzeugt',forecast.stats.produced)}${kv('Ausgeliefert',forecast.stats.delivered)}</div></div>`:''}`;}
function help(){return `<p class="fine">Betriebshandbuch · Version ${VERSION}</p><div class="notice good">Alle Firmen, Personen, Preise und Verkehrsregeln sind fiktive Spielwerte. Simulation bleibt lokal. Keine Offlinefortschritte.</div>${[
 ['Erste Zustellung','Baue eine Laderampe (Dock) und ein Lagerregal. Stelle eine Lagerkraft ein. Nimm im Vertragsfenster den ersten Frachtvertrag an. Am Vormittag kommt der erste Lkw: Er dockt an und wird entladen, die Lagerkraft sortiert die Pakete von Hand. Stelle eine Fahrperson ein und kaufe einen Lieferwagen. Ordne im Auftragsfenster die sortierten Pakete dem Fahrzeug zu, einzeln oder als Sammeltour. Eine Stunde nach der Zustellung zahlt der Versender. „Startbetrieb einrichten“ in der Zentrale übernimmt den Aufbau über reguläre Befehle (ca. 14.500 €).'],
 ['Wirtschaftlichkeit im Depot','Erlös je Paket steht im Vertrag, meist 7 bis 8,50 €. Gewinn entsteht über die Menge. Laufende Kosten: Löhne je Schichtminute (Lagerkraft und Fahrer zusammen rund 310 € am Tag), Strom, Hallenmiete und Fahrtkosten je Tour (rund 5 bis 25 €). Schon der Startvertrag mit 200 bis 250 Paketen am Tag trägt Lagerkraft und Fahrer. Ein Lieferwagen fasst 160 Pakete und schafft in der Tagschicht etwa drei Touren. Mit einer Lagerkraft sind so rund 350 bis 400 Pakete am Tag pünktlich zu schaffen. Mit einem passenden zweiten Vertrag bringt ein guter Tag rund 2.200 € Überschuss; die Grundausstattung ist dann nach sechs bis sieben Spieltagen bezahlt. Zustellung nach Fristende kostet 10 % des Erlöses und Ansehen. Liegengebliebene Pakete binden am nächsten Morgen den Lieferwagen. Mehr Verträge, als Lagerkraft und Lieferwagen schaffen, bringen kaum mehr Geld, nur Verspätungen. Für mehr Menge braucht es ein weiteres Fahrzeug mit Fahrer.'],
 ['Mehrwertdienste (später)','Montage, Prüfung und Verpackung bleiben als künftiges Geschäftsfeld „Mehrwertdienste“ erhalten, etwa Kommissionierung und Verpackung für Versender. Für den Einstieg werden sie nicht benötigt. Die vorhandenen Fertigungsanlagen lassen sich weiterhin bauen.'],
 ['Frachtverträge, Hof und Docks','Verträge: Angebot prüfen (Versender, Zustellgebiete, Ankünfte je Tag, Pakete, Preis je Paket, Frist ab Tor) und annehmen. Zu jeder Ankunft kommt ein fremder Lkw: Anfahrt, Torkontrolle, Wartet auf Dock, Zum Dock, Andocken, Entladen, Ausfahrt. Ohne freies Dock oder Lagerpersonal wartet er; der Grund steht im Torbuch unter Hof & Docks. „Vorziehen“ bittet die Hofsteuerung, einen noch nicht angedockten Lkw zuerst zu bedienen. Entladene Pakete liegen im Wareneingang, ein Sortierplatz macht sie versandfähig, eigene Fahrzeuge stellen sie zu.'],
 ['Paletten und Stapler',`Ab Spieltag ${fmt(TERMS.pallet?.fromDay??3)} (oder sobald ein Staplerplatz steht) bieten Versender auch Palettenverträge an: Lkw mit mehreren Paletten je Ankunft, Preis je Palette. Paletten werden nicht sortiert. Entladen braucht eine Lagerkraft und einen freien, geladenen Stapler am Standort; die Paletten gehen direkt ins Lager. Zustellen kann nur ein Lkw, Lieferwagen tragen keine Paletten. Jeder Staplerplatz (Baumodus, Symbol ⇈) hat einen Stapler mit Akku: Arbeit kostet ${fmt(FORKLIFT.work,1)} % je Minute, im Leerlauf lädt er ${fmt(FORKLIFT.charge)} % je Minute, nur mit Strom am Standort. Unter ${fmt(FORKLIFT.min)} % ist er nicht einsatzbereit. Wartegründe im Torbuch: „Kein Stapler“, „Stapler lädt“, „Kein Strom für Stapler“. Akku und Tätigkeit stehen in der Akte des Staplerplatzes und unter Hof & Docks. Die Glocke warnt bei Akku unter ${fmt(FORKLIFT_WARN)} % und bei Palettenvertrag ohne Staplerplatz oder Lkw.`],
 ['Vertragsstrafen',`Jeder Frachtvertrag nennt zwei Strafsätze je Einheit. Verspätet: Für jedes Paket bzw. jede Palette, die nach der Frist zugestellt wird, fällt zusätzlich zum Abschlag von 10 % die Verspätungsstrafe an (Paket ${rateEuro(TERMS.penalty?.parcel?.late??1.5)}, Palette ${rateEuro(TERMS.penalty?.pallet?.late??8)}). Liegengeblieben: ${fmt((TERMS.penalty?.openGrace??1440)/60)} Stunden nach Vertragsende kostet jede noch nicht zugestellte Einheit Strafe (Paket ${rateEuro(TERMS.penalty?.parcel?.open??4)}, Palette ${rateEuro(TERMS.penalty?.pallet?.open??20)}); der Auftrag wird storniert, freie Ware geht an den Versender zurück. Liegt Ware dann noch auf einem Fahrzeug, ist reserviert oder steht ein Lkw im Hof, zeigt die Vertragskarte „Abrechnung wartet“ bis zum Abschluss. Jede Strafe wird genau einmal gebucht, Kategorie „Vertragsstrafe“ in der Unternehmensrechnung. Die Vertragskarte zeigt angefallene Strafen. Die Glocke meldet „Strafe droht“, sobald ein Vertragsauftrag in weniger als ${fmt(PENALTY_WARN)} Minuten fällig ist und noch Menge offen hat.`],
 ['Material und Maschinen','Gehäuse + Platine → montierte Leuchte. Prüfstation → geprüfte Leuchte. Packstation + Karton → verkaufbare Leuchte. Anlagen wählen automatisch ihren ersten Arbeitsplan. Jedes Stück benötigt Arbeitszeit, Personal und Strom.'],
 ['Warum wartet mein Betrieb?','Material fehlt: Einkauf und Wareneingang prüfen. Personal fehlt: Rolle, Schicht und andere Tätigkeiten prüfen. Ausgang blockiert: Lager erweitern oder Ware ausliefern. Energie fehlt: Versorgung ausbauen. Gebäude anklicken für Details.'],
 ['Schichten und Zeit','Tagschicht: 08 bis 16 Uhr. Nachtschicht: 16 bis 08 Uhr. Durchgehend ist eine vereinfachte Spieloption mit Müdigkeit. Zeitraffer steuert nur Spielgeschwindigkeit. Hintergrund und geschlossene Seite erzeugen keinen Fortschritt.'],
 ['Bauen und Wege','Baumodus mit B öffnen. Anlage wählen und Rasterfläche anklicken. R dreht gewählte Anlage. Wege vom Wareneingang müssen zu allen Anlagen offen bleiben. Laufende Arbeitsvorgänge verhindern Abriss. Leere Anlage kann über ihre Akte versetzt werden.'],
 ['Lager, Ladung und Zahlung','Reservierte Ware ist für andere Aufträge gesperrt. Eine Lieferung darf vorhandene Ware und Ladeplätze nicht überschreiten. Nach Zustellung entsteht Forderung; Zahlung kommt später. Jeder Geldeingang besitzt genau einen Buchungsschlüssel.'],
 ['HTML-Datei speichern','In Einstellungen: Spiel als HTML speichern. Download enthält vollständiges Spiel und aktuellen Spielstand. Datei öffnen, Betrieb mit 1× fortsetzen. Weiteren Fortschritt erneut als HTML herunterladen; Originaldatei wird nicht automatisch überschrieben.'],
 ['Speichern und Sicherung','Auf der Website: Automatische Sicherung alle 20 Sekunden sowie beim Verlassen. Derselbe Modus besitzt nur einen schreibenden Tab; weitere Tabs bleiben pausiert. Modus laden in Einstellungen erhält vorhandene Unternehmen. Nach Laden oder Neugründung startet Betrieb pausiert: 1× drücken. Jeder Spielmodus besitzt eigenen Speicherplatz und letzte Sicherung. Exportiere JSON regelmäßig für geräteunabhängige Aufbewahrung. Import wird vor Übernahme geprüft.'],
 ['Steuerung und Zugänglichkeit','/: Suche nach Anlagen, Fahrzeugen, Kennzeichen, Verträgen, Aufträgen und Beschäftigten; Pfeiltasten und Eingabe öffnen die Akte. Glocke: aktuelle Wartegründe und Warnungen. Standortfluss und Fahrzeugleiste lassen sich einklappen; ▢ blendet alle Panels aus. Leertaste: Pause. B: Bauen. R: Bauobjekt drehen. Escape: Fenster schließen. Ziehen: Kamera bewegen. Mausrad: Zoom. Grundriss liefert ebene Ersatzansicht. Alle Anlagen auch über Fertigungstabelle auswählen. Schrift und Bewegung in Einstellungen.'],
 ['Darstellung und Umfang','Die aktuelle räumliche Ansicht verwendet lokal gezeichnete Canvas-Isometrie. Sie benötigt kein WebGL. Phasenstatus und konkrete Grenzen sind in der ausgelieferten Dokumentation nachgehalten.']
 ].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}`;}
function backupNotice(){if(portableMode||temporary)return '';const key=STORE+'-'+recoveryMode();let prev=false;try{prev=store.has(key+'-backup-prev');}catch{}
 if(prev){const t=previousTime(key);return `<div class="notice">Sicherung des vorherigen Unternehmens${typeof t==='number'?' ('+esc(time(t))+')':''} bleibt erhalten (eigener Platz). Der aktuelle Stand hat seine eigene laufende Sicherung.</div>${started?`<div class="actions">${button('Vorheriges Unternehmen laden','loadPrevious')}${button('Alte Sicherung verwerfen','discardBackup','','danger')}</div>`:''}`;}
 const meta=holdMeta(key);if(!meta)return '';return `<div class="notice">Sicherung des vorherigen Unternehmens${typeof meta.t==='number'?' ('+esc(time(meta.t))+')':''} bleibt erhalten. Bis zum Verwerfen erhält der aktuelle Stand keine eigene Sicherung.</div>${started?`<div class="actions">${button('Alte Sicherung verwerfen','discardBackup','','danger')}</div>`:''}`;}
function settings(){return `<section class="section"><h3>Spielstand</h3><p class="fine">HTML-Download enthält Spiel und aktuellen Stand. Datei im Browser öffnen, dann 1× drücken. Für späteren Fortschritt erneut als HTML speichern. Keine Installation nötig.</p>${temporary?`<div class="notice">${temporaryMessage}</div>`:''}${!portableMode?`<div class="actions">${button('Speicher erneut prüfen','retryStorage')}${!temporary?button('Ohne lokale Speicherung spielen','temporary'):''}</div>`:''}${!writable&&!temporary?`<div class="notice">${esc(lockMessage())}</div>`:''}${!portableMode?`<form data-form="loadMode" class="form-grid">${field('Gespeichertes Unternehmen','<select name="mode"><option value="guided">Geführter Einstieg</option><option value="economy">Wirtschaftsbetrieb</option><option value="sandbox">Freies Bauen</option></select>')}<button>Modus laden</button></form>`:''}<p class="fine">Version ${VERSION}. Vollständiger Funktionsstatus und Quellcode im Download.</p>${!portableMode?'<p style="margin:10px 0"><a href="./Industrie-Logistik.zip" download>Spielpaket & Quellcode herunterladen ↗</a></p>':''}<p class="fine" style="margin-top:8px">Aktiver Modus: ${sim.state.mode==='guided'?'Geführter Einstieg':sim.state.mode==='sandbox'?'Freies Bauen':'Wirtschaftsbetrieb'}</p><div class="actions">${button('Spiel als HTML speichern','exportHtml','','primary')}${!portableMode?button('Im Browser speichern','save'):''}${button('JSON exportieren','export')}${button('JSON importieren','import')}${!portableMode&&backupAvailable(recoveryMode())?button('Letzte Sicherung laden','backup'):''}</div>${backupNotice()}</section><section class="section"><h3>Darstellung</h3><div class="list-row"><span>Größere Schrift</span><input type="checkbox" data-pref="large" ${prefs.large?'checked':''} aria-label="Größere Schrift"></div><div class="list-row"><span>Bewegung reduzieren</span><input type="checkbox" data-pref="reduced" ${prefs.reduced?'checked':''} aria-label="Bewegung reduzieren"></div><div class="list-row"><span>Einstiegshinweise</span><input type="checkbox" data-pref="mission" ${prefs.mission?'checked':''} aria-label="Einstiegshinweise"></div></section><section class="section"><h3>Unternehmen</h3><div class="actions">${button('Neues Unternehmen','new','','danger')}${button('Handbuch','panel-help')}</div><p class="fine" style="margin-top:10px">Neustart erfolgt erst nach Bestätigung. Vorheriger Stand kann exportiert werden.</p></section><div class="notice">Browserprüfung dieser Veröffentlichung noch offen. Fachliche Simulation wird automatisiert geprüft.</div>`;}
function confirm(title,text,action){$('#confirmTitle').textContent=title;$('#confirmText').textContent=text;confirmAction=action;$('#confirm').showModal();}
// Depot-Grundausstattung (A02 W1b): nur reguläre Befehle; bereits Vorhandenes wird nicht doppelt gekauft. Bricht bei fehlendem Kapital ab.
