function updateTourDraft(form){tourDraft=Object.fromEntries(new FormData(form));for(const i of [1,2,3,4]){const q=form.querySelector?.(`input[name="qty${i}"]`),h=form.querySelector?.(`[data-tour-max="${i}"]`);if(q)q.max=String(tourStopMax(sim.state,tourDraft,i));if(h)h.textContent=tourStopHint(sim.state,tourDraft,i);}const preview=form.querySelector('[data-tour-preview]');if(preview)preview.innerHTML=tourPreview(sim.state,tourDraft);}
function driverForecastCard(f){if(!f)return '';return `<div class="notice">${f.elapsedMinutes==null?'<b>Fahrerprognose nicht verfügbar</b>':`${kv('Geschätzte Gesamtzeit mit Fahrpersonal',fmt(f.elapsedMinutes)+' Min.')}${kv('Davon Wartezeit',fmt(f.waitMinutes)+' Min.')}${kv('Pausen / Schichtwartezeit',fmt(f.breakMinutes)+' / '+fmt(f.shiftMinutes)+' Min.')}`}<p class="fine">${esc(f.assumption||'Freie Rampe und verfügbares Lagerpersonal vorausgesetzt. Keine verbindliche Ankunftszeit.')}</p></div>`;}
function tourPreview(s,d){const command=tourCommand(d);if(command.stops.length<2)return '<p class="fine">Zwei bis vier unterschiedliche Aufträge wählen. Reihenfolge entspricht Fahrtfolge.</p>';const plan=planTour(s,command.vehicleId,command.stops);if(!plan.ok)return `<div class="notice">${esc(plan.message)}</div>`;const v=s.vehicles.find(v=>v.id===command.vehicleId),weightCapacity=VEHICLES[v.type].weightCapacity||v.capacity*4;const initial=command.stops.reduce((a,st)=>{const item=ITEMS[s.orders.find(o=>o.id===st.orderId).item];a.volume+=st.qty*(item.volume||1);a.weight+=st.qty*(item.weight||1);return a;},{volume:0,weight:0});return `${kv('Fahrtkosten',euro(plan.cost))}${kv('Arbeits- und Fahrtzeit',fmt(plan.minutes)+' Min.')}${driverForecastCard(plan.driverForecast)}${kv('Strecke',fmt(plan.distance)+' km')}${kv('Startladung',fmt(initial.volume)+' / '+fmt(v.capacity)+' Volumen · '+fmt(initial.weight)+' / '+fmt(weightCapacity)+' kg')}<ol class="tour-stops">${plan.stops.map(st=>`<li><b>${esc(s.orders.find(o=>o.id===st.orderId)?.customer||st.orderId)}</b><small>${fmt(st.qty)} zustellen · ${fmt(st.returnQty||0)} zurücknehmen</small><small>Danach: ${fmt(st.volume)} / ${fmt(v.capacity)} Volumen · ${fmt(st.weight)} / ${fmt(weightCapacity)} kg</small></li>`).join('')}</ol><p class="fine">Zeit ohne zusätzliche Schicht-, Pausen- und Engpasswartezeiten. Fahrtkosten ohne Löhne und Erstattungen. Bestand und Verfügbarkeit werden bei Beauftragung erneut geprüft.</p>`;}
function tourCard(s,t){const v=s.vehicles.find(v=>v.id===t.vehicleId),capacity=v?.capacity||0,weightCapacity=VEHICLES[v?.type]?.weightCapacity||capacity*4;const ids=new Set(t.stops.flatMap(st=>[...(st.cargo||[]),...((s.returns||[]).find(r=>r.id===st.returnId)?.cargo||[])]));const cargo=s.batches.filter(b=>ids.has(b.id)&&b.location==='vehicle'&&b.qty>0);const load=cargo.reduce((a,b)=>{a.volume+=b.qty*(ITEMS[b.item]?.volume||1);a.weight+=b.qty*(ITEMS[b.item]?.weight||1);return a;},{volume:0,weight:0});return `<div class="card tour-card"><div class="card-top"><h3>${esc(t.id)}</h3>${badge(label(t.status),t.blocked?'warn':'')}</div>${kv('Fahrzeug',esc(v?.name||t.vehicleId))}${kv('Aktuelle Phase verbleibend',fmt(t.remaining)+' Min.')}${kv(t.transportCost==null?'Fahrtkosten':'Gebuchte Fahrtkosten',t.transportCost==null?'Bei Abfahrt':euro(t.transportCost))}${kv('Ladung an Bord',fmt(load.volume)+' / '+fmt(capacity)+' Volumen · '+fmt(load.weight)+' / '+fmt(weightCapacity)+' kg')}${t.blocked?`<div class="notice" role="status">${esc(t.blocked)}</div>`:''}<ol class="tour-stops">${(t.stops||[]).map((st,i)=>{const r=(s.returns||[]).find(r=>r.id===st.returnId);return `<li ${i===t.stopIndex&&!['complete','cancelled','loading','returning','returnUnloading'].includes(t.status)?'aria-current="step"':''}><b>${esc(s.orders.find(o=>o.id===st.orderId)?.customer||st.orderId)}</b><small>${fmt(st.qty)} Stück · ${st.status==='delivered'?'zugestellt':label(st.status==='pending'?'scheduled':st.status)}</small>${r?.qty?`<small>Rückladung: ${fmt(r.qty)} Stück · ${esc(r?label(r.status):'Eingeplant')}</small>`:''}</li>`;}).join('')}</ol>${t.status==='loading'?button('Tour vor Abfahrt stornieren','cancelTour',t.id):''}</div>`;}
function tourPanel(s){const active=s.orders.filter(o=>o.status==='active'),vehicles=s.vehicles.filter(v=>v.site===s.selectedSite&&v.status==='idle');if(!tourDraft.vehicleId&&vehicles[0])tourDraft.vehicleId=vehicles[0].id;return `<section class="section"><h3>Sammeltour mit Rückladung</h3><p class="fine" style="margin:8px 0 14px">Zustellen, danach Rückladung aufnehmen. Rückgabe nur für bereits gelieferte, noch nicht retournierte Ware desselben Auftrags. Rückfahrt endet mit Entladung in Quarantäne.</p><form data-form="tour" class="form-grid">${field('Fahrzeug',`<select name="vehicleId">${vehicles.map(v=>`<option value="${v.id}" ${tourDraft.vehicleId===v.id?'selected':''}>${esc(v.name)} · ${fmt(v.capacity)} Vol. · ${fmt(weightCap(v))} kg${VEHICLES[v.type]?.cold?' · Kühlung':''}</option>`).join('')||'<option value="">Kein freies Fahrzeug</option>'}</select>`,true)}${[1,2,3,4].map(i=>`<fieldset class="tour-stop-input"><legend>Stopp ${i}</legend>${field('Auftrag',`<select name="order${i}"><option value="">${i<3?'Kunde auswählen':'Optionaler Stopp'}</option>${active.map(o=>`<option value="${o.id}" ${tourDraft['order'+i]===o.id?'selected':''}>${esc(o.customer)} · ${o.qty-o.delivered} offen · ${o.delivered} geliefert</option>`).join('')}</select>`,true)}<div class="grid2"><label class="field">Zustellmenge<span class="fine" data-tour-max="${i}">${tourStopHint(s,tourDraft,i)}</span><input name="qty${i}" type="number" value="${esc(tourDraft['qty'+i]??2)}" min="1" max="${tourStopMax(s,tourDraft,i)}" step="1" required></label>${field('Rückgabemenge',`<input name="returnQty${i}" type="number" value="${esc(tourDraft['returnQty'+i]??0)}" min="0" max="1000" step="1" required>`)}</div></fieldset>`).join('')}<div class="tour-preview" data-tour-preview aria-live="polite">${tourPreview(s,tourDraft)}</div><button class="primary">Sammeltour verbindlich planen</button></form><div class="section-title" style="margin-top:20px"><h3>Beauftragte Touren</h3></div>${(s.tours||[]).slice().reverse().map(t=>tourCard(s,t)).join('')||empty('Keine Sammeltouren')}</section>`;}


function special(){const s=sim.state,cold=s.batches.filter(b=>b.qty>0&&ITEMS[b.item]?.cold);return `<div class="notice">Kalibriermodule benötigen passende Kühlung. Temperatur wirkt über Zeit auf Qualität. Frachtklassen und Dokumente folgen fiktiven Spielregeln.</div><section class="section"><h3>Kühlkette</h3>${cold.map(b=>`<div class="card" style="margin-top:10px"><div class="card-top"><h3>${b.qty} × ${esc(name(ITEMS,b.item))}</h3>${badge(b.blocked?'Gesperrt':label(b.location),b.blocked?'bad':'')}</div>${kv('Temperatur',fmt(b.temperature??20,1)+' °C')}${kv('Qualität',fmt(b.quality,1)+' %')}${kv('Wärmeexposition',fmt(b.exposure||0)+' Min.')}${button('Chargenakte','select',b.id)}${b.coldDamaged&&b.owner==='company'?button('Entsorgen · 2 €/Stk.','disposeBatch',b.id,'danger'):''}</div>`).join('')||empty('Keine temperaturgeführte Ware','Forschung Kühlkettenlogistik, Kühllager und Kühlfahrzeug vorbereiten.')}</section><section class="section"><h3>Bahn, See und Luft</h3><p class="fine" style="margin:8px 0 15px">Buchbare Fremdleistungen ab eigenem Terminal. Dokumentprüfung, Umschlag und Fahrplan bestimmen tatsächliche Abfahrt.</p><form data-form="freight" class="form-grid">${field('Aktiver Auftrag',`<select name="orderId">${s.orders.filter(o=>o.status==='active').map(o=>`<option value="${o.id}">${esc(o.customer)} · ${esc(name(ITEMS,o.item))}</option>`).join('')||'<option value="">Kein aktiver Auftrag</option>'}</select>`,true)}${field('Verkehrsträger','<select name="mode"><option value="rail">Bahn</option><option value="sea">Seefracht</option><option value="air">Luftfracht</option></select>')}${field('Menge','<input name="qty" type="number" min="1" max="1000" value="8">')}<button class="primary">Fracht verbindlich buchen</button></form></section><section class="section"><h3>Frachtaufträge</h3>${(s.freights||[]).slice().reverse().map(f=>`<div class="card" style="margin-top:10px"><div class="card-top"><h3>${esc(label(f.mode))} · ${f.qty} Stück</h3>${badge(label(f.status),f.blocked?'warn':'')}</div>${kv('Auftrag',esc(s.orders.find(o=>o.id===f.orderId)?.customer||f.orderId))}${kv(f.departedAt?'Abgefahren':'Nächster Fahrplan',time(f.departedAt||f.nextDeparture))}${kv('Dokumente',f.documents==='approved'?'Freigegeben':f.documents==='processing'?'Prüfung · '+f.documentRemaining+' Min.':'Prüfung erforderlich')}${kv('Verpasste Anschlüsse',fmt(f.missedConnections||0))}${kv('Restzeit',fmt(f.remaining)+' Min.')}${f.blocked?`<p>${esc(f.blocked)}</p>`:''}<div class="actions">${f.documents==='pending'&&f.status!=='cancelled'?button('Dokumentprüfung starten','approveDocuments',f.id):''}${button('Akte','select',f.id)}${['loading','waiting'].includes(f.status)?button('Stornieren · Fracht verfällt','cancelFreight',f.id):''}</div></div>`).join('')||empty('Keine gebuchten Frachten')}</section>`;}

/** Einheitliche Auswertung aller tatsächlichen Zustellungen, ohne neue Geldbuchung. */
function deliveryRows(s){return [...s.shipments,...(s.freights||[]).map(f=>({...f,transportCost:f.tripCost??f.transportCost})),...(s.tours||[]).flatMap(t=>t.stops.map((st,i)=>({...st,id:t.id+' / '+(i+1),transportCost:(t.transportCost||0)*st.qty/t.stops.reduce((n,x)=>n+x.qty,0)})))];}
